// دادهٔ ساختگی برای اجرای محلی تست‌های بات (هیچ اسم، شماره یا chat واقعی اینجا نیاید).
// شیت‌های حافظه‌ای gas-local.mjs را با حداقل داده‌ای پر می‌کند که مسیرهای اصلی (پرسش‌های متداول،
// شروع، پذیرش، نمایش وقت‌های خالی و رزرو معارفه) را بشود بدون شیت زنده سنجید.

const DAYS = ['شنبه', 'یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه'];

function put(sh, rowNo, values) { values.forEach((v, j) => sh.put(rowNo, j + 1, v)); }

export function seedFixtures(bot) {
  const id = bot.run('TG_SHEET_ID');
  const ss = bot.book(id);
  const tab = (name) => ss.getSheetByName(name) || ss.insertSheet(name);

  // درمانگران: سرستون در سطر ۳، داده از سطر ۴ (tgTherapistRows_)
  const ther = tab(bot.run('TG_THER'));
  const head = [];
  head[0] = 'نام'; head[1] = 'وضعیت همکاری'; head[2] = 'جنسیت'; head[3] = 'حالت جلسه';
  head[19] = 'استخر خودرزرو'; head[21] = 'کد'; head[22] = 'chat_id'; head[25] = 'معرفی کوتاه'; head[26] = 'لینک جلسه';
  put(ther, 3, Array.from({ length: 27 }, (_, i) => head[i] || ''));
  const people = [
    ['درمانگر نمونه الف', 'فعال', 'زن', 'آنلاین'],
    ['درمانگر نمونه ب', 'فعال', 'مرد', 'آنلاین'],
    ['درمانگر نمونه پ', 'فعال', 'زن', 'آنلاین و حضوری'],
  ];
  people.forEach((p, i) => {
    const row = Array.from({ length: 27 }, () => '');
    row[0] = p[0]; row[1] = p[1]; row[2] = p[2]; row[3] = p[3];
    row[19] = 'هر دو'; row[25] = 'معرفی کوتاه ساختگی برای تست.';
    // اولی عمداً لینک جلسه ندارد (مسیر «بعد از اتصال لینک جلسه را بخواه» در tgSignupTests)
    row[26] = i === 0 ? '' : 'https://meet.example.invalid/test-' + (i + 1);
    put(ther, 4 + i, row);
  });

  // وقت‌های هفتگی معارفه: نام · روز · ساعت · استخر · فعال (tgWeeklyRules_)
  const wk = tab(bot.run('TG_WEEKLY'));
  put(wk, 3, ['درمانگر', 'روز', 'ساعت', 'استخر', 'فعال', 'یادداشت', 'نوع']);
  let r = 4;
  for (const d of DAYS) {
    people.forEach((p, i) => { put(wk, r++, [p[0], d, (10 + i * 3) + ':00', 'هر دو', 'بله', '', 'معارفه']); });
  }

  // اسلات معارفه: فقط سرستون (رزروها اینجا نوشته می‌شوند)
  put(tab(bot.run('TG_SLOTS')), 3, ['درمانگر', 'تاریخ', 'روز', 'ساعت', 'مراجع', 'وضعیت', 'استخر']);

  // لیدها: فقط سرستون (بعضی مسیرها مثل لغو معارفه پروندهٔ مراجع را جست‌وجو می‌کنند)
  const lh = ['تاریخ', 'ساعت', 'منبع', 'نام', 'کانال', 'شماره', 'منطقه', 'اولین پیام', 'وضعیت', 'مسئول', 'تاریخ تماس'];
  lh[36] = 'کد لید'; lh[37] = 'اعلان بات';
  put(tab(bot.run('TG_LEADS')), 1, Array.from({ length: 38 }, (_, i) => lh[i] || ''));

  // سؤالات متداول: پرسش · پاسخ · نمایش
  const faq = tab(bot.run('TG_FAQ'));
  put(faq, 3, ['پرسش', 'پاسخ', 'نمایش']);
  put(faq, 4, ['هزینهٔ جلسه چقدر است؟', 'هزینه در پیام پذیرش گفته می‌شود. (متن ساختگی تست)', 'بله']);
  put(faq, 5, ['جلسه آنلاین است؟', 'بله، آنلاین و حضوری. (متن ساختگی تست)', 'بله']);
}
